import type { ContentPack } from '../types';
import { glesson as G, lesson, M, mix, Nq, TF } from '../lib';
import { gears, lever, ohm } from '../gensSci';
import { loops, robot, scale, spreadsheet } from '../gens';

const P: ContentPack = {
  '1E-TD-1': lesson(['Para buscar información técnica: define bien qué buscas, usa palabras clave y operadores (comillas para frases exactas), consulta varias fuentes fiables, comprueba fecha y autoría y guarda los enlaces para citarlos.|Per a buscar informació tècnica: definix bé què busques, usa paraules clau i operadors (cometes per a frases exactes), consulta diverses fonts fiables, comprova data i autoria i guarda els enllaços per a citar-los.|To find technical information: define clearly what you need, use keywords and operators (quotes for exact phrases), check several reliable sources, look at the date and author and save links to cite them.'],
    '¿Cómo busco solo páginas con la frase exacta «puente levadizo»?|Com busque només pàgines amb la frase exacta «pont llevadís»?|How do I search only for pages with the exact phrase "drawbridge mechanism"?', ['Las comillas fuerzan la frase exacta.|Les cometes forcen la frase exacta.|Quotes force the exact phrase.', 'Escribo "puente levadizo" entre comillas.|Escric "pont llevadís" entre cometes.|I type "drawbridge mechanism" in quotes.'], [
      M('¿Qué fuente es más fiable para un dato técnico?|Quina font és més fiable per a una dada tècnica?|Which source is most reliable for a technical fact?', 'el manual del fabricante|el manual del fabricant|the manufacturer’s manual', ['un comentario anónimo|un comentari anònim|an anonymous comment', 'un meme|un mem|a meme'], 'Fuente original.|Font original.|The original source.'),
      TF('Conviene contrastar la información en más de una fuente.|Convé contrastar la informació en més d’una font.|It is wise to check information in more than one source.', true, 'Así detectas errores.|Així detectes errors.|That way you spot mistakes.'),
      M('Filtrar información significa…|Filtrar informació significa…|Filtering information means…', 'quedarse con lo útil y fiable|quedar-se amb el que és útil i fiable|keeping what is useful and reliable', ['copiarlo todo|copiar-ho tot|copying everything', 'borrar el historial|esborrar l’historial|clearing your history'], 'Seleccionar.|Seleccionar.|Selecting.'),
      M('Para buscar en un sitio web concreto se puede usar…|Per a buscar en un lloc web concret es pot usar…|To search within one website you can use…', 'site:|site:|site:', ['#|#|#', '@|@|@'], 'Ejemplo: site:edu.gva.es tecnología.|Exemple: site:edu.gva.es tecnologia.|Example: site:edu.gva.es technology.'),
      TF('La primera página de resultados siempre es la más fiable.|La primera pàgina de resultats sempre és la més fiable.|The first result is always the most reliable.', false, 'Puede ser publicidad o posicionamiento.|Pot ser publicitat o posicionament.|It may be advertising or SEO.'),
      M('¿Qué dato ayuda a valorar si una web está actualizada?|Quina dada ajuda a valorar si una web està actualitzada?|What helps you tell if a website is up to date?', 'la fecha de publicación|la data de publicació|the publication date', ['el color del logo|el color del logo|the logo colour', 'el tamaño de letra|la mida de lletra|the font size'], 'La tecnología cambia rápido.|La tecnologia canvia ràpid.|Technology changes fast.'),
    ]),
  '1E-TD-2': lesson(['Fases del proyecto técnico: identificar el problema, buscar información, diseñar (bocetos y croquis), planificar (materiales, herramientas, tareas), construir, evaluar (¿funciona?, ¿se puede mejorar?) y comunicar.|Fases del projecte tècnic: identificar el problema, buscar informació, dissenyar (esbossos i croquis), planificar (materials, eines, tasques), construir, avaluar (funciona?, es pot millorar?) i comunicar.|Stages of a technology project: identify the problem, research, design (sketches and drawings), plan (materials, tools, tasks), build, evaluate (does it work? can it be improved?) and present.'],
    'Queremos una caja que mantenga frío el almuerzo. ¿Primer paso?|Volem una caixa que mantinga fred l’esmorzar. Primer pas?|We want a box that keeps lunch cold. First step?', ['Definir bien el problema y las condiciones.|Definir bé el problema i les condicions.|Define the problem and requirements clearly.', 'Después buscar información sobre aislantes.|Després buscar informació sobre aïllants.|Then research insulating materials.'], [
      M('¿Qué fase va después de diseñar?|Quina fase va després de dissenyar?|Which stage comes after designing?', 'planificar|planificar|planning', ['evaluar|avaluar|evaluating', 'identificar el problema|identificar el problema|identifying the problem'], 'Materiales, herramientas y tareas.|Materials, eines i tasques.|Materials, tools and tasks.'),
      M('Evaluar el proyecto consiste en…|Avaluar el projecte consistix en…|Evaluating the project means…', 'comprobar si resuelve el problema y cómo mejorarlo|comprovar si resol el problema i com millorar-lo|checking whether it solves the problem and how to improve it', ['tirarlo|llançar-lo|throwing it away', 'pintarlo|pintar-lo|painting it'], 'Pruebas y mejoras.|Proves i millores.|Testing and improving.'),
      TF('En un proyecto en grupo conviene repartir tareas.|En un projecte en grup convé repartir tasques.|In a group project it helps to share tasks.', true, 'Cada persona con su rol.|Cada persona amb el seu rol.|Each person has a role.'),
      M('La hoja de planificación incluye…|El full de planificació inclou…|The planning sheet includes…', 'tareas, responsables y plazos|tasques, responsables i terminis|tasks, people responsible and deadlines', ['solo el título|només el títol|only the title', 'la nota final|la nota final|the final mark'], 'Organizar el trabajo.|Organitzar el treball.|Organising the work.'),
      M('Un presupuesto de proyecto recoge…|Un pressupost de projecte arreplega…|A project budget lists…', 'el coste de los materiales|el cost dels materials|the cost of materials', ['los nombres del grupo|els noms del grup|the group’s names', 'el horario de clase|l’horari de classe|the timetable'], 'Cuánto cuesta construirlo.|Quant costa construir-lo.|How much it costs to build.'),
      TF('Si el prototipo falla, el proyecto ha sido inútil.|Si el prototip falla, el projecte ha sigut inútil.|If the prototype fails, the project was useless.', false, 'Los fallos enseñan a mejorar.|Els errors ensenyen a millorar.|Failures teach you how to improve.'),
    ]),
  '1E-TD-3': lesson(['Un prototipo es un primer modelo para probar una idea. Se construye con materiales sencillos (cartón, madera, plástico reciclado), siguiendo el diseño, y se prueba y mejora en ciclos: diseñar → construir → probar → mejorar.|Un prototip és un primer model per a provar una idea. Es construïx amb materials senzills (cartó, fusta, plàstic reciclat), seguint el disseny, i es prova i millora en cicles: dissenyar → construir → provar → millorar.|A prototype is a first model to test an idea. It is built from simple materials (card, wood, recycled plastic) following the design, then tested and improved in cycles: design → build → test → improve.'],
    'Mi puente de palillos se dobla con poco peso. ¿Qué hago?|El meu pont d’escuradents es doblega amb poc pes. Què faig?|My lolly-stick bridge bends under a small load. What do I do?', ['Analizo dónde falla.|Analitze on falla.|Work out where it fails.', 'Añado triángulos para hacerlo más rígido y vuelvo a probar.|Afig triangles per a fer-lo més rígid i torne a provar.|Add triangles to stiffen it and test again.'], [
      M('¿Para qué sirve un prototipo?|Per a què servix un prototip?|What is a prototype for?', 'para probar una idea antes del producto final|per a provar una idea abans del producte final|to test an idea before the final product', ['para venderlo enseguida|per a vendre’l de seguida|to sell it straight away', 'para decorar|per a decorar|for decoration'], 'Detectar fallos pronto.|Detectar errors prompte.|Find problems early.'),
      M('El triángulo se usa en estructuras porque…|El triangle s’usa en estructures perquè…|Triangles are used in structures because…', 'es una forma indeformable|és una forma indeformable|they do not change shape under load', ['es más bonito|és més bonic|they look nicer', 'pesa más|pesa més|they are heavier'], 'Triangulación.|Triangulació.|Triangulation.'),
      TF('Reutilizar materiales en los prototipos reduce residuos.|Reutilitzar materials en els prototips reduïx residus.|Reusing materials in prototypes cuts waste.', true, 'Cartón, botellas, tapones…|Cartó, botelles, taps…|Card, bottles, lids…'),
      M('Tras probar un prototipo, el siguiente paso es…|Després de provar un prototip, el pas següent és…|After testing a prototype, the next step is…', 'mejorarlo según los resultados|millorar-lo segons els resultats|improving it based on the results', ['tirarlo|llançar-lo|throwing it away', 'no tocarlo más|no tocar-lo més|leaving it as it is'], 'Ciclo de mejora.|Cicle de millora.|An improvement cycle.'),
      M('Para unir cartón de forma rápida se usa…|Per a unir cartó de manera ràpida s’usa…|To join card quickly you use…', 'cola blanca o pistola de silicona|cola blanca o pistola de silicona|PVA glue or a glue gun', ['soldadura|soldadura|welding', 'tornillos de acero|cargols d’acer|steel bolts'], 'Con cuidado con la pistola caliente.|Amb compte amb la pistola calenta.|Careful with the hot glue gun.'),
      TF('Un prototipo debe ser perfecto a la primera.|Un prototip ha de ser perfecte a la primera.|A prototype must be perfect first time.', false, 'Se mejora con pruebas.|Es millora amb proves.|It improves with testing.'),
    ]),
  '1E-TD-4': G(['El dibujo técnico comunica ideas: boceto (a mano alzada, rápido), croquis (con medidas) y plano (preciso, a escala). Las vistas principales son alzado (de frente), planta (desde arriba) y perfil (de lado). La perspectiva muestra el objeto en 3D.|El dibuix tècnic comunica idees: esbós (a mà alçada, ràpid), croquis (amb mesures) i plànol (precís, a escala). Les vistes principals són alçat (de front), planta (des de dalt) i perfil (de costat). La perspectiva mostra l’objecte en 3D.|Technical drawing communicates ideas: sketch (freehand, quick), working drawing (with measurements) and plan (precise, to scale). The main views are front elevation, plan (from above) and side elevation. Perspective shows the object in 3D.'],
    'Una pieza mide 6 cm en un plano a escala 1:2. ¿Medida real?|Una peça mesura 6 cm en un plànol a escala 1:2. Mesura real?|A part is 6 cm on a 1:2 scale drawing. Real size?', ['1:2: lo real es el doble.|1:2: el real és el doble.|1:2: real size is double.', '12 cm.|12 cm.|12 cm.'], scale(), [
      M('La vista desde arriba se llama…|La vista des de dalt s’anomena…|The view from above is called the…', 'planta|planta|plan', ['alzado|alçat|front elevation', 'perfil|perfil|side elevation'], 'Como un mapa.|Com un mapa.|Like a map.'),
      M('Un dibujo rápido a mano alzada para expresar una idea es…|Un dibuix ràpid a mà alçada per a expressar una idea és…|A quick freehand drawing to express an idea is a…', 'un boceto|un esbós|sketch', ['un plano|un plànol|plan', 'una maqueta|una maqueta|model'], 'Sin medidas precisas.|Sense mesures precises.|No exact measurements.'),
      TF('Un croquis incluye las medidas del objeto.|Un croquis inclou les mesures de l’objecte.|A working sketch includes the object’s measurements.', true, 'Aunque sea a mano alzada.|Encara que siga a mà alçada.|Even if freehand.'),
      M('La escala 2:1 significa que el dibujo es…|L’escala 2:1 significa que el dibuix és…|A 2:1 scale means the drawing is…', 'el doble de grande que la realidad|el doble de gran que la realitat|twice real size', ['la mitad|la meitat|half real size', 'igual|igual|the same size'], 'Escala de ampliación.|Escala d’ampliació.|An enlarging scale.'),
    ]),
  '1E-TD-5': lesson(['La memoria técnica documenta el proyecto: índice, descripción del problema, soluciones estudiadas, solución elegida, planos, lista de materiales y presupuesto, planificación, proceso de construcción, evaluación y conclusiones. Se puede presentar con diapositivas o un vídeo.|La memòria tècnica documenta el projecte: índex, descripció del problema, solucions estudiades, solució triada, plànols, llista de materials i pressupost, planificació, procés de construcció, avaluació i conclusions. Es pot presentar amb diapositives o un vídeo.|The technical report documents the project: contents, the problem, solutions considered, chosen solution, drawings, materials list and budget, plan, building process, evaluation and conclusions. It can be presented with slides or a video.'],
    '¿Para qué sirve la memoria técnica?|Per a què servix la memòria tècnica?|What is the technical report for?', ['Explica cómo y por qué se hizo cada cosa.|Explica com i per què es va fer cada cosa.|It explains how and why everything was done.', 'Permite que otros repitan o mejoren el proyecto.|Permet que altres repetisquen o milloren el projecte.|Others can repeat or improve the project.'], [
      M('¿Qué apartado incluye el coste de los materiales?|Quin apartat inclou el cost dels materials?|Which section includes the cost of materials?', 'el presupuesto|el pressupost|the budget', ['la portada|la portada|the cover', 'el índice|l’índex|the contents'], 'Lista y precio.|Llista i preu.|List and price.'),
      TF('Las fotos del proceso de construcción enriquecen la memoria.|Les fotos del procés de construcció enriquixen la memòria.|Photos of the building process improve the report.', true, 'Muestran los pasos.|Mostren els passos.|They show the steps.'),
      M('En las conclusiones se explica…|En les conclusions s’explica…|The conclusions explain…', 'si se cumplió el objetivo y qué se mejoraría|si es va complir l’objectiu i què es milloraria|whether the aim was met and what could be improved', ['la lista de herramientas|la llista d’eines|the tool list', 'el título|el títol|the title'], 'Reflexión final.|Reflexió final.|Final reflection.'),
      M('Una buena diapositiva tiene…|Una bona diapositiva té…|A good slide has…', 'poco texto y una imagen clara|poc text i una imatge clara|little text and a clear image', ['párrafos largos|paràgrafs llargs|long paragraphs', 'diez colores distintos|deu colors diferents|ten different colours'], 'Se lee de un vistazo.|Es llig d’un colp d’ull.|Readable at a glance.'),
      TF('En la memoria se deben citar las fuentes consultadas.|En la memòria s’han de citar les fonts consultades.|The report should cite the sources used.', true, 'Webs, libros, manuales.|Webs, llibres, manuals.|Websites, books, manuals.'),
      M('El índice sirve para…|L’índex servix per a…|The contents page is used to…', 'encontrar rápido cada apartado|trobar ràpid cada apartat|find each section quickly', ['decorar|decorar|decorate', 'poner la nota|posar la nota|give the mark'], 'Con números de página.|Amb números de pàgina.|With page numbers.'),
    ]),
  '1E-TD-6': lesson(['Materiales de uso técnico: madera (natural, renovable), metales (conducen, resistentes: acero, aluminio, cobre), plásticos (ligeros, aislantes, moldeables), pétreos (piedra, hormigón), cerámicos y textiles. Propiedades: dureza, elasticidad, tenacidad, conductividad, densidad.|Materials d’ús tècnic: fusta (natural, renovable), metalls (condueixen, resistents: acer, alumini, coure), plàstics (lleugers, aïllants, modelables), petris (pedra, formigó), ceràmics i tèxtils. Propietats: duresa, elasticitat, tenacitat, conductivitat, densitat.|Technical materials: wood (natural, renewable), metals (conductive, strong: steel, aluminium, copper), plastics (light, insulating, mouldable), stone-based (stone, concrete), ceramics and textiles. Properties: hardness, elasticity, toughness, conductivity, density.'],
    '¿Por qué los cables son de cobre recubierto de plástico?|Per què els cables són de coure recobert de plàstic?|Why are cables made of copper covered in plastic?', ['El cobre conduce muy bien la electricidad.|El coure conduïx molt bé l’electricitat.|Copper conducts electricity very well.', 'El plástico aísla y protege.|El plàstic aïlla i protegix.|Plastic insulates and protects.'], [
      M('La dureza es la resistencia a…|La duresa és la resistència a…|Hardness is resistance to…', 'ser rayado|ser ratllat|being scratched', ['romperse por un golpe|trencar-se per un colp|breaking from a blow', 'conducir calor|conduir calor|conducting heat'], 'El diamante es el más duro.|El diamant és el més dur.|Diamond is the hardest.'),
      M('Un material elástico…|Un material elàstic…|An elastic material…', 'recupera su forma tras deformarse|recupera la seua forma després de deformar-se|returns to shape after being deformed', ['se rompe fácilmente|es trenca fàcilment|breaks easily', 'no se deforma nunca|no es deforma mai|never deforms'], 'Como una goma.|Com una goma.|Like a rubber band.'),
      M('¿Qué material es renovable?|Quin material és renovable?|Which material is renewable?', 'la madera|la fusta|wood', ['el aluminio|l’alumini|aluminium', 'el plástico de petróleo|el plàstic de petroli|oil-based plastic'], 'Si se replantan árboles.|Si es replanten arbres.|If trees are replanted.'),
      TF('El vidrio es frágil: se rompe fácilmente con un golpe.|El vidre és fràgil: es trenca fàcilment amb un colp.|Glass is brittle: it breaks easily when struck.', true, 'Lo contrario de tenaz.|El contrari de tenaç.|The opposite of tough.'),
      M('Las latas de refresco suelen ser de…|Les llaunes de refresc solen ser d’…|Drink cans are usually made of…', 'aluminio|alumini|aluminium', ['madera|fusta|wood', 'hormigón|formigó|concrete'], 'Ligero y reciclable.|Lleuger i reciclable.|Light and recyclable.'),
      M('El hormigón es un material…|El formigó és un material…|Concrete is a…', 'pétreo|petri|stone-based material', ['textil|tèxtil|textile', 'metálico|metàl·lic|metal'], 'Cemento, arena, grava y agua.|Ciment, arena, grava i aigua.|Cement, sand, gravel and water.'),
    ]),
  '1E-TD-7': lesson(['Una estructura soporta cargas sin romperse ni deformarse demasiado. Elementos: pilares, vigas, tirantes, cimientos, arcos. Esfuerzos: tracción (estirar), compresión (aplastar), flexión (doblar), torsión (retorcer) y cortadura (cortar).|Una estructura suporta càrregues sense trencar-se ni deformar-se massa. Elements: pilars, bigues, tirants, fonaments, arcs. Esforços: tracció (estirar), compressió (aixafar), flexió (doblegar), torsió (retorçar) i cisallament (tallar).|A structure carries loads without breaking or bending too much. Parts: columns, beams, ties, foundations, arches. Forces: tension (pulling), compression (squashing), bending, torsion (twisting) and shear (cutting).'],
    '¿Qué esfuerzo soporta la cuerda de un columpio?|Quin esforç suporta la corda d’un gronxador?|Which force acts on the rope of a swing?', ['El peso tira de ella.|El pes estira d’ella.|The weight pulls on it.', 'Tracción.|Tracció.|Tension.'], [
      M('Una columna que soporta un techo sufre…|Una columna que suporta un sostre patix…|A column holding up a roof is under…', 'compresión|compressió|compression', ['tracción|tracció|tension', 'torsión|torsió|torsion'], 'La aplastan.|L’aixafen.|It is squashed.'),
      M('Una estantería que se dobla por el centro sufre…|Una prestatgeria que es doblega pel centre patix…|A shelf sagging in the middle is under…', 'flexión|flexió|bending', ['compresión|compressió|compression', 'cortadura|cisallament|shear'], 'Se curva.|Es corba.|It curves.'),
      M('Al girar una llave en la cerradura, la llave sufre…|En girar una clau en el pany, la clau patix…|Turning a key in a lock puts the key under…', 'torsión|torsió|torsion', ['tracción|tracció|tension', 'flexión|flexió|bending'], 'Se retuerce.|Es retorç.|It is twisted.'),
      TF('Los cimientos transmiten el peso del edificio al suelo.|Els fonaments transmeten el pes de l’edifici al sòl.|Foundations pass the building’s weight to the ground.', true, 'Base de la estructura.|Base de l’estructura.|The base of the structure.'),
      M('Las tijeras producen sobre el papel un esfuerzo de…|Les tisores produïxen sobre el paper un esforç de…|Scissors put paper under…', 'cortadura|cisallament|shear', ['torsión|torsió|torsion', 'compresión|compressió|compression'], 'Dos fuerzas opuestas muy cerca.|Dues forces oposades molt prop.|Two opposing forces close together.'),
      M('Para que una estructura de barras sea rígida se usan…|Perquè una estructura de barres siga rígida s’usen…|To make a frame rigid you use…', 'triángulos|triangles|triangles', ['cuadrados|quadrats|squares', 'círculos|cercles|circles'], 'Triangulación.|Triangulació.|Triangulation.'),
    ]),
  '1E-TD-8': lesson(['Herramientas del taller: de medir y marcar (regla, escuadra, metro, lápiz), de sujetar (tornillo de banco, sargento), de cortar (sierra de marquetería, segueta, tijeras), de perforar (taladro), de unir (martillo, destornillador, pistola de cola) y de acabado (lija, lima). Seguridad: gafas, guantes, orden y uso correcto.|Eines del taller: de mesurar i marcar (regle, escaire, metre, llapis), de subjectar (cargol de banc, serjant), de tallar (serra de marqueteria, segueta, tisores), de perforar (trepant), d’unir (martell, tornavís, pistola de cola) i d’acabat (paper de vidre, llima). Seguretat: ulleres, guants, ordre i ús correcte.|Workshop tools: measuring and marking (ruler, try square, tape measure, pencil), holding (vice, G-clamp), cutting (coping saw, junior hacksaw, scissors), drilling (drill), joining (hammer, screwdriver, glue gun) and finishing (sandpaper, file). Safety: goggles, gloves, tidiness and correct use.'],
    '¿Qué haces antes de taladrar una pieza?|Què fas abans de trepar una peça?|What do you do before drilling a piece?', ['Marcar el punto y sujetar la pieza.|Marcar el punt i subjectar la peça.|Mark the spot and clamp the piece.', 'Ponerse gafas de protección.|Posar-se ulleres de protecció.|Put on safety goggles.'], [
      M('Para cortar curvas en una lámina de madera se usa…|Per a tallar corbes en una làmina de fusta s’usa…|To cut curves in thin wood you use a…', 'la sierra de marquetería|la serra de marqueteria|coping saw', ['el martillo|el martell|hammer', 'el destornillador|el tornavís|screwdriver'], 'Hoja fina.|Fulla fina.|Thin blade.'),
      M('Para comprobar ángulos rectos se usa…|Per a comprovar angles rectes s’usa…|To check right angles you use a…', 'la escuadra|l’escaire|try square', ['la lima|la llima|file', 'el sargento|el serjant|G-clamp'], 'Forma de L.|Forma de L.|L-shaped.'),
      TF('Se debe sujetar la pieza con el tornillo de banco antes de serrarla.|S’ha de subjectar la peça amb el cargol de banc abans de serrar-la.|Clamp the piece in a vice before sawing.', true, 'Evita accidentes y cortes torcidos.|Evita accidents i talls torts.|It prevents accidents and crooked cuts.'),
      M('Para alisar los bordes de una pieza de madera se usa…|Per a allisar les vores d’una peça de fusta s’usa…|To smooth the edges of wood you use…', 'lija|paper de vidre|sandpaper', ['martillo|martell|a hammer', 'taladro|trepant|a drill'], 'Acabado.|Acabat.|Finishing.'),
      M('Al usar la pistola de silicona hay que…|En usar la pistola de silicona cal…|When using a glue gun you must…', 'no tocar la boquilla caliente|no tocar el broquet calent|not touch the hot nozzle', ['soplar la cola|bufar la cola|blow on the glue', 'dejarla encendida al irse|deixar-la encesa en anar-se’n|leave it on when you leave'], 'Puede quemar.|Pot cremar.|It can burn.'),
      TF('Es seguro llevar el pelo suelto cerca del taladro.|És segur portar els cabells solts prop del trepant.|It is safe to have loose hair near a drill.', false, 'Puede engancharse.|Es pot enganxar.|It can get caught.'),
    ]),
  '1E-TD-9': G(['Una palanca es una barra que gira sobre un punto de apoyo. Ley de la palanca: F · d = R · r (fuerza por su brazo = resistencia por su brazo). Tipos: 1.er grado (apoyo en medio: balancín), 2.º (resistencia en medio: carretilla), 3.er (fuerza en medio: pinzas).|Una palanca és una barra que gira sobre un punt de suport. Llei de la palanca: F · d = R · r (força pel seu braç = resistència pel seu braç). Tipus: 1r grau (suport al mig: balancí), 2n (resistència al mig: carretó), 3r (força al mig: pinces).|A lever is a bar that turns on a pivot. Law of the lever: effort × its distance = load × its distance. Classes: 1st (pivot in the middle: seesaw), 2nd (load in the middle: wheelbarrow), 3rd (effort in the middle: tweezers).'],
    'Para levantar 200 N a 10 cm del apoyo, empujo a 50 cm. ¿Fuerza?|Per a alçar 200 N a 10 cm del suport, empente a 50 cm. Força?|To lift 200 N at 10 cm from the pivot, I push at 50 cm. Effort?', ['F · 50 = 200 · 10.|F · 50 = 200 · 10.|F × 50 = 200 × 10.', 'F = 40 N.|F = 40 N.|F = 40 N.'], lever(), [
      M('Una carretilla es una palanca de…|Un carretó és una palanca de…|A wheelbarrow is a…', '2.º grado|2n grau|2nd-class lever', ['1.er grado|1r grau|1st-class lever', '3.er grado|3r grau|3rd-class lever'], 'La carga está entre la rueda y las manos.|La càrrega està entre la roda i les mans.|The load is between the wheel and your hands.'),
      M('Unas pinzas de depilar son una palanca de…|Unes pinces de depilar són una palanca de…|Tweezers are a…', '3.er grado|3r grau|3rd-class lever', ['1.er grado|1r grau|1st-class lever', '2.º grado|2n grau|2nd-class lever'], 'La fuerza está en medio.|La força està al mig.|The effort is in the middle.'),
    ]),
  '1E-TD-10': G(['Los mecanismos de transmisión circular (poleas con correa, engranajes) transmiten el giro. Relación de transmisión i = z₁ / z₂ (o d₁ / d₂ en poleas). Si la rueda motriz es más pequeña, el conducido gira más despacio (reductor); si es más grande, más deprisa (multiplicador). n₁ · z₁ = n₂ · z₂.|Els mecanismes de transmissió circular (politges amb corretja, engranatges) transmeten el gir. Relació de transmissió i = z₁ / z₂ (o d₁ / d₂ en politges). Si la roda motriu és més xicoteta, el conduït gira més a poc a poc (reductor); si és més gran, més de pressa (multiplicador). n₁ · z₁ = n₂ · z₂.|Rotary transmission (belt and pulleys, gears) passes on turning motion. Ratio i = z₁ ÷ z₂ (or d₁ ÷ d₂ for pulleys). If the driver is smaller, the driven wheel turns more slowly (reduction); if larger, faster (step-up). n₁ × z₁ = n₂ × z₂.'],
    'Plato de 40 dientes y piñón de 10 en una bici. Una vuelta de pedal, ¿cuántas da la rueda?|Plat de 40 dents i pinyó de 10 en una bici. Una volta de pedal, quantes en fa la roda?|A bike has a 40-tooth chainring and a 10-tooth sprocket. One turn of the pedals turns the wheel how many times?', ['i = 40 / 10 = 4.|i = 40 / 10 = 4.|i = 40 ÷ 10 = 4.', '4 vueltas: multiplicador.|4 voltes: multiplicador.|4 turns: a step-up.'], gears()),
  '1E-TD-11': G(['Un circuito eléctrico tiene generador (pila), conductores (cables), receptores (bombilla, motor, zumbador) y elementos de control (interruptor, pulsador). En serie, los receptores están uno tras otro; en paralelo, cada uno en su rama. Ley de Ohm: V = I · R.|Un circuit elèctric té generador (pila), conductors (cables), receptors (bombeta, motor, brunzidor) i elements de control (interruptor, polsador). En sèrie, els receptors estan un darrere de l’altre; en paral·lel, cadascun en la seua branca. Llei d’Ohm: V = I · R.|An electric circuit has a supply (battery), conductors (wires), components (bulb, motor, buzzer) and controls (switch, push button). In series, components are one after another; in parallel, each has its own branch. Ohm’s law: V = I × R.'],
    'Dos bombillas en paralelo. Una se funde. ¿Qué pasa con la otra?|Dues bombetes en paral·lel. Una es fon. Què passa amb l’altra?|Two bulbs in parallel. One blows. What happens to the other?', ['Cada una tiene su propio camino.|Cada una té el seu propi camí.|Each has its own path.', 'Sigue encendida.|Continua encesa.|It stays on.'], ohm(), [
      M('¿Qué elemento abre y cierra el circuito?|Quin element obri i tanca el circuit?|Which part opens and closes the circuit?', 'el interruptor|l’interruptor|the switch', ['la bombilla|la bombeta|the bulb', 'la pila|la pila|the battery'], 'Elemento de control.|Element de control.|A control component.'),
      M('Un motor eléctrico transforma la electricidad en…|Un motor elèctric transforma l’electricitat en…|An electric motor turns electricity into…', 'movimiento|moviment|movement', ['luz|llum|light', 'sonido|so|sound'], 'Energía mecánica.|Energia mecànica.|Mechanical energy.'),
    ]),
  '1E-TD-12': lesson(['Un ordenador tiene hardware (partes físicas) y software (programas). Hardware: placa base, procesador (CPU), memoria RAM, almacenamiento (disco SSD), periféricos de entrada (teclado, ratón), de salida (pantalla, impresora) y de entrada/salida (pantalla táctil). Software: sistema operativo y aplicaciones.|Un ordinador té maquinari (parts físiques) i programari (programes). Maquinari: placa base, processador (CPU), memòria RAM, emmagatzematge (disc SSD), perifèrics d’entrada (teclat, ratolí), d’eixida (pantalla, impressora) i d’entrada/eixida (pantalla tàctil). Programari: sistema operatiu i aplicacions.|A computer has hardware (physical parts) and software (programs). Hardware: motherboard, processor (CPU), RAM, storage (SSD), input devices (keyboard, mouse), output devices (screen, printer) and input/output devices (touchscreen). Software: operating system and apps.'],
    '¿Qué hace la memoria RAM?|Què fa la memòria RAM?|What does RAM do?', ['Guarda lo que se está usando en ese momento.|Guarda el que s’està usant en eixe moment.|It holds what is being used right now.', 'Se borra al apagar el ordenador.|S’esborra en apagar l’ordinador.|It is wiped when the computer is switched off.'], [
      M('El «cerebro» del ordenador es…|El «cervell» de l’ordinador és…|The computer’s "brain" is the…', 'el procesador (CPU)|el processador (CPU)|processor (CPU)', ['el ratón|el ratolí|mouse', 'la impresora|la impressora|printer'], 'Hace los cálculos.|Fa els càlculs.|It does the calculations.'),
      M('Un teclado es un periférico de…|Un teclat és un perifèric d’…|A keyboard is an…', 'entrada|entrada|input device', ['salida|eixida|output device', 'almacenamiento|emmagatzematge|storage device'], 'Introduce datos.|Introduïx dades.|It puts data in.'),
      M('Una impresora es un periférico de…|Una impressora és un perifèric d’…|A printer is an…', 'salida|eixida|output device', ['entrada|entrada|input device', 'procesamiento|processament|processing device'], 'Saca información.|Trau informació.|It puts information out.'),
      M('El sistema operativo es…|El sistema operatiu és…|The operating system is…', 'software que gestiona el ordenador|programari que gestiona l’ordinador|software that runs the computer', ['una pieza de hardware|una peça de maquinari|a piece of hardware', 'un cable|un cable|a cable'], 'Windows, Linux, macOS, Android…|Windows, Linux, macOS, Android…|Windows, Linux, macOS, Android…'),
      TF('Una pantalla táctil es de entrada y salida.|Una pantalla tàctil és d’entrada i eixida.|A touchscreen is both input and output.', true, 'Muestra y recibe toques.|Mostra i rep tocs.|It displays and receives touches.'),
      M('Los archivos se guardan de forma permanente en…|Els fitxers es guarden de manera permanent en…|Files are stored permanently on…', 'el disco (SSD o HDD)|el disc (SSD o HDD)|the drive (SSD or HDD)', ['la RAM|la RAM|RAM', 'el ratón|el ratolí|the mouse'], 'No se borra al apagar.|No s’esborra en apagar.|It is not wiped when switched off.'),
    ]),
  '1E-TD-13': lesson(['Las plataformas de aprendizaje (como Aules en la Comunitat Valenciana) permiten acceder a materiales, entregar tareas, ver calificaciones y comunicarse con el profesorado. Se usan con usuario y contraseña propios, organizando las carpetas y respetando los plazos y las normas de convivencia.|Les plataformes d’aprenentatge (com Aules a la Comunitat Valenciana) permeten accedir a materials, lliurar tasques, veure qualificacions i comunicar-se amb el professorat. S’usen amb usuari i contrasenya propis, organitzant les carpetes i respectant els terminis i les normes de convivència.|Learning platforms (such as Aules in the Valencia region) let you access materials, hand in work, see marks and talk to teachers. Use them with your own login, keep folders tidy, and respect deadlines and rules.'],
    '¿Qué debes hacer antes de entregar una tarea?|Què has de fer abans de lliurar una tasca?|What should you do before handing in a task?', ['Revisar que el archivo es el correcto y se abre.|Revisar que el fitxer és el correcte i s’obri.|Check the file is the right one and opens.', 'Ponerle un nombre claro y entregar dentro del plazo.|Posar-li un nom clar i lliurar dins del termini.|Give it a clear name and hand it in on time.'], [
      TF('Está bien compartir tu contraseña con un amigo.|Està bé compartir la teua contrasenya amb un amic.|It is fine to share your password with a friend.', false, 'Es personal.|És personal.|It is personal.'),
      M('Un buen nombre de archivo es…|Un bon nom de fitxer és…|A good file name is…', 'Tecno_Proyecto1_AnaPerez.pdf|Tecno_Projecte1_AnaPerez.pdf|Tech_Project1_AnaPerez.pdf', ['documento final final 2.pdf|document final final 2.pdf|final final document 2.pdf', 'aaaa.pdf|aaaa.pdf|aaaa.pdf'], 'Claro y sin espacios.|Clar i sense espais.|Clear, with no spaces.'),
      M('En un foro de clase hay que…|En un fòrum de classe cal…|In a class forum you should…', 'escribir con respeto|escriure amb respecte|write respectfully', ['escribir en mayúsculas|escriure en majúscules|write in capitals', 'insultar si no estás de acuerdo|insultar si no estàs d’acord|insult people you disagree with'], 'Netiqueta.|Netiqueta.|Netiquette.'),
      TF('Conviene cerrar sesión en ordenadores compartidos.|Convé tancar la sessió en ordinadors compartits.|Log out on shared computers.', true, 'Protege tu cuenta.|Protegix el teu compte.|It protects your account.'),
      M('El formato PDF es útil para entregar porque…|El format PDF és útil per a lliurar perquè…|PDF is useful for handing in because…', 'se ve igual en cualquier dispositivo|es veu igual en qualsevol dispositiu|it looks the same on any device', ['ocupa siempre más|ocupa sempre més|it is always larger', 'no se puede abrir|no es pot obrir|it cannot be opened'], 'Mantiene el formato.|Manté el format.|It keeps the layout.'),
      M('Si no puedes entregar a tiempo por un problema técnico…|Si no pots lliurar a temps per un problema tècnic…|If a technical problem stops you handing in on time…', 'avisa al profesor cuanto antes|avisa el professor com més prompte millor|tell the teacher as soon as possible', ['no digas nada|no digues res|say nothing', 'entrega otro archivo cualquiera|lliura un altre fitxer qualsevol|hand in any old file'], 'Comunicación.|Comunicació.|Communication.'),
    ]),
  '1E-TD-14': lesson(['Herramientas ofimáticas: procesador de textos (documentos con títulos, listas, imágenes), hoja de cálculo (tablas, cálculos, gráficos) y presentaciones (diapositivas para exponer). Conviene usar estilos, guardar a menudo y elegir formatos abiertos (ODT, ODS, ODP) o compatibles.|Eines ofimàtiques: processador de textos (documents amb títols, llistes, imatges), full de càlcul (taules, càlculs, gràfics) i presentacions (diapositives per a exposar). Convé usar estils, guardar sovint i triar formats oberts (ODT, ODS, ODP) o compatibles.|Office tools: word processor (documents with headings, lists, images), spreadsheet (tables, calculations, charts) and presentations (slides for talks). Use styles, save often and choose open (ODT, ODS, ODP) or compatible formats.'],
    '¿Qué herramienta usas para calcular las notas medias de la clase?|Quina eina uses per a calcular les notes mitjanes de la classe?|Which tool do you use to work out average marks?', ['Hay números y cálculos.|Hi ha nombres i càlculs.|It involves numbers and calculations.', 'La hoja de cálculo.|El full de càlcul.|A spreadsheet.'], [
      M('Para escribir un informe con títulos e índice se usa…|Per a escriure un informe amb títols i índex s’usa…|To write a report with headings and contents you use a…', 'un procesador de textos|un processador de textos|word processor', ['una hoja de cálculo|un full de càlcul|spreadsheet', 'un editor de vídeo|un editor de vídeo|video editor'], 'Writer, Word, Docs…|Writer, Word, Docs…|Writer, Word, Docs…'),
      M('Los estilos de título sirven para…|Els estils de títol servixen per a…|Heading styles help to…', 'dar formato uniforme y crear el índice automático|donar format uniforme i crear l’índex automàtic|keep formatting consistent and build the contents automatically', ['cambiar el idioma|canviar l’idioma|change the language', 'borrar el texto|esborrar el text|delete text'], 'Ahorran tiempo.|Estalvien temps.|They save time.'),
      TF('ODT es un formato abierto de documento de texto.|ODT és un format obert de document de text.|ODT is an open text-document format.', true, 'De LibreOffice.|De LibreOffice.|Used by LibreOffice.'),
      M('Una presentación sirve sobre todo para…|Una presentació servix sobretot per a…|A presentation is mainly used to…', 'apoyar una exposición oral|recolzar una exposició oral|support a spoken talk', ['hacer cálculos|fer càlculs|do calculations', 'programar robots|programar robots|programme robots'], 'Impress, PowerPoint, Slides…|Impress, PowerPoint, Slides…|Impress, PowerPoint, Slides…'),
      M('Para no perder trabajo conviene…|Per a no perdre treball convé…|To avoid losing work you should…', 'guardar a menudo|guardar sovint|save often', ['no guardar nunca|no guardar mai|never save', 'apagar sin guardar|apagar sense guardar|switch off without saving'], 'Ctrl + S.|Ctrl + S.|Ctrl + S.'),
      M('Insertar una imagen de Internet en un trabajo exige…|Inserir una imatge d’Internet en un treball exigix…|Using an image from the internet in your work requires…', 'respetar su licencia y citar el autor|respectar la seua llicència i citar l’autor|respecting its licence and crediting the author', ['nada|res|nothing', 'cambiarle el color|canviar-li el color|changing its colour'], 'Busca imágenes con licencia libre.|Busca imatges amb llicència lliure.|Look for openly licensed images.'),
    ]),
  '1E-TD-15': G(['En una hoja de cálculo, cada celda tiene una dirección (A1, B3). Las fórmulas empiezan por = y pueden usar operaciones (+ − * /) y funciones (SUMA, PROMEDIO, MAX, MIN). Si cambias un dato, todo se recalcula. Con los datos se crean gráficos.|En un full de càlcul, cada cel·la té una adreça (A1, B3). Les fórmules comencen per = i poden usar operacions (+ − * /) i funcions (SUMA, MITJANA, MÀX, MÍN). Si canvies una dada, tot es recalcula. Amb les dades es creen gràfics.|In a spreadsheet, each cell has an address (A1, B3). Formulae start with = and can use operations (+ − * /) and functions (SUM, AVERAGE, MAX, MIN). Change a value and everything recalculates. Charts are made from the data.'],
    'A1 = 5, A2 = 7, A3 = 9. ¿=PROMEDIO(A1:A3)?|A1 = 5, A2 = 7, A3 = 9. =MITJANA(A1:A3)?|A1 = 5, A2 = 7, A3 = 9. =AVERAGE(A1:A3)?', ['(5 + 7 + 9) / 3.|(5 + 7 + 9) / 3.|(5 + 7 + 9) ÷ 3.', '7.|7.|7.'], spreadsheet()),
  '1E-TD-16': lesson(['Proteger dispositivos y datos: contraseñas largas y distintas para cada servicio, verificación en dos pasos, actualizar el sistema y las apps, antivirus, copias de seguridad, no abrir adjuntos ni enlaces sospechosos y no conectarse a wifis públicas sin precaución.|Protegir dispositius i dades: contrasenyes llargues i diferents per a cada servei, verificació en dos passos, actualitzar el sistema i les aplicacions, antivirus, còpies de seguretat, no obrir adjunts ni enllaços sospitosos i no connectar-se a wifis públiques sense precaució.|Protecting devices and data: long, different passwords for each service, two-step verification, updating the system and apps, antivirus, backups, not opening suspicious attachments or links, and caution on public Wi-Fi.'],
    'Te llega un correo: «Tu cuenta será bloqueada, entra aquí y pon tu contraseña». ¿Qué haces?|Et ve un correu: «El teu compte serà bloquejat, entra ací i posa la teua contrasenya». Què fas?|You get an email: "Your account will be locked, click here and enter your password". What do you do?', ['Es un intento de phishing (suplantación).|És un intent de pesca (phishing).|It is a phishing attempt.', 'No hago clic; lo borro o aviso a un adulto.|No faig clic; l’esborre o avise un adult.|Do not click; delete it or tell an adult.'], [
      M('¿Qué contraseña es más segura?|Quina contrasenya és més segura?|Which password is strongest?', 'Gat0-verd*Platja!9|Gat0-verd*Platja!9|Gat0-verd*Platja!9', ['123456|123456|123456', 'contraseña|contrasenya|password'], 'Larga y con distintos tipos de caracteres.|Llarga i amb diferents tipus de caràcters.|Long with different kinds of characters.'),
      M('La verificación en dos pasos añade…|La verificació en dos passos afig…|Two-step verification adds…', 'un segundo código además de la contraseña|un segon codi a més de la contrasenya|a second code as well as the password', ['otra contraseña igual|una altra contrasenya igual|the same password again', 'nada|res|nothing'], 'Más difícil de robar la cuenta.|Més difícil de robar el compte.|Harder to steal the account.'),
      TF('Las actualizaciones corrigen fallos de seguridad.|Les actualitzacions corregixen errors de seguretat.|Updates fix security holes.', true, 'Conviene instalarlas.|Convé instal·lar-les.|Install them.'),
      M('Una copia de seguridad sirve para…|Una còpia de seguretat servix per a…|A backup is used to…', 'recuperar los datos si se pierden|recuperar les dades si es perden|recover data if it is lost', ['hacer el ordenador más rápido|fer l’ordinador més ràpid|make the computer faster', 'navegar sin pagar|navegar sense pagar|browse without paying'], 'En otro disco o en la nube.|En un altre disc o en el núvol.|On another drive or in the cloud.'),
      TF('Usar la misma contraseña en todas partes es buena idea.|Usar la mateixa contrasenya en tot arreu és bona idea.|Using the same password everywhere is a good idea.', false, 'Si roban una, entran en todo.|Si en roben una, entren en tot.|If one is stolen, they get into everything.'),
      M('Un programa malicioso que cifra tus archivos y pide un rescate es…|Un programa maliciós que xifra els teus fitxers i demana un rescat és…|Malware that locks your files and demands payment is…', 'ransomware|ransomware|ransomware', ['un antivirus|un antivirus|antivirus', 'un navegador|un navegador|a browser'], 'Por eso las copias de seguridad.|Per això les còpies de seguretat.|Hence backups.'),
    ]),
  '1E-TD-17': lesson(['Tu identidad digital es lo que se sabe de ti en Internet: perfiles, fotos, comentarios. Cuídala: piensa antes de publicar, configura la privacidad y no compartas datos personales. El bienestar digital es usar la tecnología de forma equilibrada: descansos, dormir sin pantallas, desconectar.|La teua identitat digital és el que se sap de tu en Internet: perfils, fotos, comentaris. Cuida-la: pensa abans de publicar, configura la privacitat i no compartisques dades personals. El benestar digital és usar la tecnologia de manera equilibrada: descansos, dormir sense pantalles, desconnectar.|Your digital identity is what is known about you online: profiles, photos, comments. Look after it: think before posting, set privacy controls and do not share personal data. Digital wellbeing means balanced technology use: breaks, screen-free sleep, switching off.'],
    '¿Qué pasa con una foto que subes a Internet?|Què passa amb una foto que puges a Internet?|What happens to a photo you post online?', ['Otros pueden guardarla o reenviarla.|Altres poden guardar-la o reenviar-la.|Others can save or forward it.', 'Es muy difícil borrarla del todo.|És molt difícil esborrar-la del tot.|It is very hard to remove completely.'], [
      M('¿Qué dato NO debes publicar en abierto?|Quina dada NO has de publicar en obert?|Which detail should you NOT post publicly?', 'tu dirección de casa|la teua adreça de casa|your home address', ['tu película favorita|la teua pel·lícula preferida|your favourite film', 'tu color preferido|el teu color preferit|your favourite colour'], 'Datos personales.|Dades personals.|Personal data.'),
      TF('Antes de subir una foto de otra persona hay que pedirle permiso.|Abans de pujar una foto d’una altra persona cal demanar-li permís.|Ask permission before posting a photo of someone else.', true, 'Derecho a la propia imagen.|Dret a la pròpia imatge.|Their right to their own image.'),
      M('Una buena práctica de bienestar digital es…|Una bona pràctica de benestar digital és…|A good digital wellbeing habit is…', 'dejar el móvil fuera del dormitorio por la noche|deixar el mòbil fora del dormitori a la nit|leaving your phone outside the bedroom at night', ['mirar el móvil cada minuto|mirar el mòbil cada minut|checking your phone every minute', 'jugar hasta la madrugada|jugar fins a la matinada|gaming until the early hours'], 'Mejor descanso.|Millor descans.|Better sleep.'),
      M('La privacidad de un perfil se configura para…|La privacitat d’un perfil es configura per a…|Profile privacy settings control…', 'decidir quién ve tu contenido|decidir qui veu el teu contingut|who sees your content', ['ganar seguidores|guanyar seguidors|getting followers', 'cambiar el idioma|canviar l’idioma|the language'], 'Público, amigos, privado.|Públic, amics, privat.|Public, friends, private.'),
      TF('Lo que publicas hoy puede verlo una empresa cuando busques trabajo.|El que publiques hui ho pot veure una empresa quan busques treball.|What you post today could be seen by an employer later.', true, 'Huella digital.|Petjada digital.|Digital footprint.'),
      M('Si algo en Internet te hace sentir mal, lo mejor es…|Si alguna cosa en Internet et fa sentir malament, el millor és…|If something online upsets you, it is best to…', 'contarlo a un adulto de confianza|contar-ho a un adult de confiança|tell a trusted adult', ['guardártelo|guardar-t’ho|keep it to yourself', 'responder con insultos|respondre amb insults|reply with insults'], 'Pedir ayuda.|Demanar ajuda.|Ask for help.'),
    ]),
  '1E-TD-18': lesson(['Convivir en la red: respeto (netiqueta), no difundir bulos, no participar en el ciberacoso (ni como autor ni como espectador que comparte), denunciar contenidos dañinos y respetar la propiedad intelectual (licencias Creative Commons).|Conviure en la xarxa: respecte (netiqueta), no difondre bulos, no participar en el ciberassetjament (ni com a autor ni com a espectador que compartix), denunciar continguts nocius i respectar la propietat intel·lectual (llicències Creative Commons).|Living together online: respect (netiquette), not spreading hoaxes, not taking part in cyberbullying (neither as author nor as a bystander who shares), reporting harmful content and respecting intellectual property (Creative Commons licences).'],
    'En el grupo de clase se burlan de un compañero con un meme. ¿Qué haces?|En el grup de classe es burlen d’un company amb un mem. Què fas?|In the class chat, people mock a classmate with a meme. What do you do?', ['No reenvío ni río la gracia.|No el reenvie ni rise la gràcia.|I don’t forward it or laugh along.', 'Apoyo al compañero y lo cuento a un adulto.|Recolze el company i ho conte a un adult.|I support them and tell an adult.'], [
      M('El ciberacoso es…|El ciberassetjament és…|Cyberbullying is…', 'acosar a alguien de forma repetida por medios digitales|assetjar algú de manera repetida per mitjans digitals|repeatedly harassing someone using digital media', ['una broma sin importancia|una broma sense importància|a harmless joke', 'un videojuego|un videojoc|a video game'], 'Hace mucho daño.|Fa molt de mal.|It does real harm.'),
      M('Una licencia Creative Commons «BY» exige…|Una llicència Creative Commons «BY» exigix…|A Creative Commons "BY" licence requires…', 'citar al autor|citar l’autor|crediting the author', ['pagar|pagar|payment', 'no usarla nunca|no usar-la mai|never using it'], 'Reconocimiento.|Reconeixement.|Attribution.'),
      TF('Reenviar un mensaje humillante también es participar en el acoso.|Reenviar un missatge humiliant també és participar en l’assetjament.|Forwarding a humiliating message is also taking part in bullying.', true, 'Amplía el daño.|Amplia el mal.|It spreads the harm.'),
      M('Escribir todo en MAYÚSCULAS en un chat se interpreta como…|Escriure tot en MAJÚSCULES en un xat s’interpreta com…|Writing everything in CAPITALS in a chat comes across as…', 'gritar|cridar|shouting', ['susurrar|xiuxiuejar|whispering', 'reír|riure|laughing'], 'Netiqueta.|Netiqueta.|Netiquette.'),
      M('Antes de compartir una noticia impactante, hay que…|Abans de compartir una notícia impactant, cal…|Before sharing a shocking story, you should…', 'comprobar si es verdad|comprovar si és veritat|check whether it is true', ['compartirla rápido|compartir-la ràpid|share it fast', 'añadir más detalles|afegir més detalls|add more details'], 'Puede ser un bulo.|Pot ser un bulo.|It may be a hoax.'),
      M('Si recibes amenazas por Internet, conviene…|Si reps amenaces per Internet, convé…|If you get threats online, you should…', 'guardar pruebas, bloquear y contarlo|guardar proves, bloquejar i contar-ho|save evidence, block and tell someone', ['borrarlo todo y callar|esborrar-ho tot i callar|delete everything and stay quiet', 'responder con amenazas|respondre amb amenaces|reply with threats'], 'Capturas de pantalla.|Captures de pantalla.|Screenshots.'),
    ]),
  '1E-TD-19': lesson(['Modelar un problema es descomponerlo en partes más pequeñas (descomposición), encontrar patrones, quedarse con lo importante (abstracción) y diseñar los pasos para resolverlo (algoritmo). Es la base del pensamiento computacional.|Modelar un problema és descompondre’l en parts més xicotetes (descomposició), trobar patrons, quedar-se amb l’important (abstracció) i dissenyar els passos per a resoldre’l (algorisme). És la base del pensament computacional.|Modelling a problem means breaking it into smaller parts (decomposition), spotting patterns, focusing on what matters (abstraction) and designing the steps to solve it (algorithm). It is the basis of computational thinking.'],
    'Organizar una excursión. ¿Cómo lo descompones?|Organitzar una excursió. Com ho descompons?|Organising a school trip. How do you break it down?', ['Transporte, comida, horario, permisos, presupuesto.|Transport, menjar, horari, permisos, pressupost.|Transport, food, timetable, permissions, budget.', 'Resuelvo cada parte por separado.|Resolc cada part per separat.|Solve each part separately.'], [
      M('Abstraer es…|Abstraure és…|Abstraction is…', 'quedarse con los detalles importantes|quedar-se amb els detalls importants|keeping only the important details', ['añadir todos los detalles|afegir tots els detalls|adding every detail', 'dibujar|dibuixar|drawing'], 'Un mapa de metro es una abstracción.|Un mapa de metro és una abstracció.|A metro map is an abstraction.'),
      M('Dividir un problema grande en partes pequeñas es…|Dividir un problema gran en parts xicotetes és…|Splitting a big problem into small parts is…', 'descomposición|descomposició|decomposition', ['abstracción|abstracció|abstraction', 'depuración|depuració|debugging'], 'Divide y vencerás.|Dividix i venceràs.|Divide and conquer.'),
      TF('Reconocer patrones ayuda a reutilizar soluciones.|Reconéixer patrons ajuda a reutilitzar solucions.|Spotting patterns helps reuse solutions.', true, 'Si se repite, se generaliza.|Si es repetix, es generalitza.|If it repeats, generalise it.'),
      M('Un algoritmo es…|Un algorisme és…|An algorithm is…', 'una secuencia ordenada de pasos para resolver algo|una seqüència ordenada de passos per a resoldre alguna cosa|an ordered set of steps to solve something', ['un tipo de ordenador|un tipus d’ordinador|a type of computer', 'un error|un error|a mistake'], 'Como una receta.|Com una recepta.|Like a recipe.'),
      M('Encontrar y corregir errores en un programa se llama…|Trobar i corregir errors en un programa s’anomena…|Finding and fixing errors in a program is called…', 'depurar|depurar|debugging', ['compilar|compilar|compiling', 'descargar|descarregar|downloading'], 'En inglés, debugging.|En anglés, debugging.|Debugging.'),
      Nq('Una receta tiene 3 partes con 4 pasos cada una. ¿Cuántos pasos en total?|Una recepta té 3 parts amb 4 passos cadascuna. Quants passos en total?|A recipe has 3 parts with 4 steps each. How many steps in total?', 12, [7, 34, 16], '3 · 4.|3 · 4.|3 × 4.'),
    ]),
  '1E-TD-20': G(['La programación por bloques (Scratch, MakeCode) une piezas como un puzle: eventos (al hacer clic), movimiento, apariencia, sonido, control (repetir, si… entonces), sensores, operadores y variables.|La programació per blocs (Scratch, MakeCode) unix peces com un trencaclosques: esdeveniments (en fer clic), moviment, aparença, so, control (repetir, si… aleshores), sensors, operadors i variables.|Block programming (Scratch, MakeCode) snaps pieces together like a puzzle: events (when clicked), motion, looks, sound, control (repeat, if… then), sensing, operators and variables.'],
    'Repetir 4 veces: mover 10 pasos, girar 90°. ¿Qué dibuja?|Repetir 4 vegades: moure 10 passos, girar 90°. Què dibuixa?|Repeat 4 times: move 10 steps, turn 90°. What does it draw?', ['4 lados iguales y 4 giros de 90°.|4 costats iguals i 4 girs de 90°.|4 equal sides and 4 turns of 90°.', 'Un cuadrado.|Un quadrat.|A square.'], mix(loops(), robot(5)), [
      M('El bloque «al hacer clic en la bandera verde» es de tipo…|El bloc «en fer clic en la bandera verda» és de tipus…|The "when green flag clicked" block is an…', 'evento|esdeveniment|event', ['movimiento|moviment|motion', 'operador|operador|operator'], 'Inicia el programa.|Inicia el programa.|It starts the program.'),
      Nq('Para dibujar un triángulo equilátero, ¿cuántos grados gira en cada esquina?|Per a dibuixar un triangle equilàter, quants graus gira en cada cantó?|To draw an equilateral triangle, how many degrees does it turn at each corner?', 120, [60, 90, 180], '360 / 3.|360 / 3.|360 ÷ 3.'),
    ]),
  '1E-TD-21': G(['Variables: cajas con un nombre que guardan un valor que puede cambiar (puntos, vidas). Bucles: repiten instrucciones (repetir n veces, por siempre, hasta que). Condicionales: deciden (si… entonces… si no…).|Variables: caixes amb un nom que guarden un valor que pot canviar (punts, vides). Bucles: repetixen instruccions (repetir n vegades, per sempre, fins que). Condicionals: decidixen (si… aleshores… si no…).|Variables: named boxes holding a value that can change (score, lives). Loops: repeat instructions (repeat n times, forever, until). Conditionals: decide (if… then… else…).'],
    'puntos = 0. Repetir 5 veces: puntos = puntos + 3. ¿puntos?|punts = 0. Repetir 5 vegades: punts = punts + 3. punts?|score = 0. Repeat 5 times: score = score + 3. score?', ['Suma 3 cinco veces.|Suma 3 cinc vegades.|Add 3 five times.', '15.|15.|15.'], mix(loops(), (r) => { const v = 5 + Math.floor(r() * 6), lim = 2 + Math.floor(r() * 3);
      return Nq(`vidas = ${v}. Mientras vidas > ${lim}: vidas = vidas − 1. ¿Cuánto vale vidas al final?|vides = ${v}. Mentre vides > ${lim}: vides = vides − 1. Quant val vides al final?|lives = ${v}. While lives > ${lim}: lives = lives − 1. What is lives at the end?`, lim, [lim - 1, lim + 1, 0].filter((x) => x >= 0), 'El bucle para cuando la condición deja de cumplirse.|El bucle para quan la condició deixa de complir-se.|The loop stops when the condition is no longer true.'); }), [
      M('Un condicional «si toca el borde, rebotar» sirve para…|Un condicional «si toca la vora, rebotar» servix per a…|A conditional "if on edge, bounce" is used to…', 'tomar una decisión según una condición|prendre una decisió segons una condició|make a decision based on a condition', ['repetir siempre|repetir sempre|always repeat', 'guardar puntos|guardar punts|store points'], 'Si… entonces.|Si… aleshores.|If… then.'),
    ]),
  '1E-TD-22': lesson(['Los robots tienen sensores (perciben: luz, distancia, contacto), un controlador (decide según el programa) y actuadores (actúan: motores, luces, altavoces). La inteligencia artificial (IA) permite a las máquinas aprender de datos (reconocer imágenes, voz, recomendar). Plantea retos éticos: privacidad, sesgos, empleo.|Els robots tenen sensors (perceben: llum, distància, contacte), un controlador (decidix segons el programa) i actuadors (actuen: motors, llums, altaveus). La intel·ligència artificial (IA) permet a les màquines aprendre de dades (reconéixer imatges, veu, recomanar). Planteja reptes ètics: privacitat, biaixos, ocupació.|Robots have sensors (sense light, distance, touch), a controller (decides according to the program) and actuators (act: motors, lights, speakers). Artificial intelligence (AI) lets machines learn from data (recognising images, speech, recommending). It raises ethical issues: privacy, bias, jobs.'],
    'Un robot aspirador no choca con las paredes. ¿Por qué?|Un robot aspirador no xoca amb les parets. Per què?|A robot vacuum avoids walls. Why?', ['Tiene sensores de distancia o contacto.|Té sensors de distància o contacte.|It has distance or touch sensors.', 'El programa le hace girar al detectarlas.|El programa el fa girar en detectar-les.|Its program turns it when it detects them.'], [
      M('Un motor en un robot es…|Un motor en un robot és…|A motor in a robot is…', 'un actuador|un actuador|an actuator', ['un sensor|un sensor|a sensor', 'un programa|un programa|a program'], 'Produce movimiento.|Produïx moviment.|It produces movement.'),
      M('Un sensor de ultrasonidos sirve para medir…|Un sensor d’ultrasons servix per a mesurar…|An ultrasonic sensor measures…', 'distancias|distàncies|distance', ['temperatura|temperatura|temperature', 'colores|colors|colour'], 'Como el sónar de los murciélagos.|Com el sonar de les rates penades.|Like bat echolocation.'),
      TF('La IA aprende a partir de muchos datos.|La IA aprén a partir de moltes dades.|AI learns from lots of data.', true, 'Si los datos están sesgados, la IA también.|Si les dades estan esbiaixades, la IA també.|If the data is biased, so is the AI.'),
      M('Un ejemplo de IA en el día a día es…|Un exemple d’IA en el dia a dia és…|An everyday example of AI is…', 'el reconocimiento de voz del móvil|el reconeixement de veu del mòbil|voice recognition on a phone', ['una bombilla|una bombeta|a light bulb', 'un lápiz|un llapis|a pencil'], 'Aprende a entender la voz.|Aprén a entendre la veu.|It learns to understand speech.'),
      M('Un reto ético de la IA es…|Un repte ètic de la IA és…|An ethical challenge of AI is…', 'que tome decisiones injustas por datos sesgados|que prenga decisions injustes per dades esbiaixades|unfair decisions from biased data', ['que gaste poca energía|que gaste poca energia|using little energy', 'que sea de color gris|que siga de color gris|being grey'], 'Sesgos.|Biaixos.|Bias.'),
      TF('Conviene revisar lo que genera una IA antes de darlo por bueno.|Convé revisar el que genera una IA abans de donar-ho per bo.|You should check what an AI produces before trusting it.', true, 'Puede equivocarse.|Es pot equivocar.|It can be wrong.'),
    ]),
  '1E-TD-23': lesson(['La tecnología ha cambiado la vida humana: herramientas de piedra, rueda, imprenta, máquina de vapor (Revolución Industrial), electricidad, ordenador e Internet. Su impacto ambiental obliga a diseñar productos duraderos, reparables y reciclables (economía circular).|La tecnologia ha canviat la vida humana: eines de pedra, roda, impremta, màquina de vapor (Revolució Industrial), electricitat, ordinador i Internet. El seu impacte ambiental obliga a dissenyar productes duradors, reparables i reciclables (economia circular).|Technology has changed human life: stone tools, the wheel, printing, the steam engine (Industrial Revolution), electricity, computers and the internet. Its environmental impact means products must be durable, repairable and recyclable (circular economy).'],
    '¿Qué invento impulsó la Revolución Industrial?|Quin invent va impulsar la Revolució Industrial?|Which invention drove the Industrial Revolution?', ['Siglo XVIII, Inglaterra.|Segle XVIII, Anglaterra.|18th century, England.', 'La máquina de vapor.|La màquina de vapor.|The steam engine.'], [
      M('La imprenta de tipos móviles (Gutenberg) permitió…|La impremta de tipus mòbils (Gutenberg) va permetre…|Gutenberg’s printing press made it possible to…', 'difundir libros y conocimiento|difondre llibres i coneixement|spread books and knowledge', ['volar|volar|fly', 'producir electricidad|produir electricitat|produce electricity'], 'Siglo XV.|Segle XV.|15th century.'),
      M('La economía circular busca…|L’economia circular busca…|The circular economy aims to…', 'reutilizar y reciclar en lugar de tirar|reutilitzar i reciclar en lloc de llançar|reuse and recycle instead of throwing away', ['fabricar más rápido para tirar antes|fabricar més ràpid per a llançar abans|make things faster to throw away sooner', 'usar solo plástico|usar només plàstic|use only plastic'], 'Cerrar el ciclo de los materiales.|Tancar el cicle dels materials.|Close the materials loop.'),
      TF('Los aparatos electrónicos deben llevarse a un punto limpio.|Els aparells electrònics s’han de portar a un ecoparc.|Electronic devices should go to a recycling centre.', true, 'Contienen metales valiosos y tóxicos.|Contenen metalls valuosos i tòxics.|They contain valuable and toxic metals.'),
      M('Ordena del más antiguo al más moderno:|Ordena del més antic al més modern:|Order from oldest to newest:', 'rueda, imprenta, máquina de vapor, Internet|roda, impremta, màquina de vapor, Internet|wheel, printing press, steam engine, internet', ['Internet, rueda, imprenta, máquina de vapor|Internet, roda, impremta, màquina de vapor|internet, wheel, printing press, steam engine', 'imprenta, Internet, rueda, máquina de vapor|impremta, Internet, roda, màquina de vapor|printing press, internet, wheel, steam engine'], 'Miles de años de historia.|Milers d’anys d’història.|Thousands of years of history.'),
      M('Un producto reparable…|Un producte reparable…|A repairable product…', 'dura más y genera menos residuos|dura més i genera menys residus|lasts longer and creates less waste', ['contamina más|contamina més|pollutes more', 'es siempre más caro de usar|és sempre més car d’usar|always costs more to use'], 'Derecho a reparar.|Dret a reparar.|Right to repair.'),
      M('El reciclaje del aluminio ahorra mucha energía porque…|El reciclatge de l’alumini estalvia molta energia perquè…|Recycling aluminium saves lots of energy because…', 'fundirlo cuesta mucho menos que obtenerlo del mineral|fondre’l costa molt menys que obtindre’l del mineral|melting it uses far less energy than extracting it from ore', ['el aluminio es renovable|l’alumini és renovable|aluminium is renewable', 'no se puede reciclar|no es pot reciclar|it cannot be recycled'], 'Hasta un 95 % menos.|Fins a un 95 % menys.|Up to 95% less.'),
    ]),
};
export default P;
